CREATE OR REPLACE FUNCTION public.vip_save_perk(p_id uuid, p_programme uuid, p_kind text, p_title text, p_description text, p_image text, p_metric text, p_threshold bigint, p_sort integer, p_active boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if not public.vip_scope_ok(p_programme) then raise exception 'Only the owner can change perks for every market; market leads change their own.'; end if;
  if btrim(coalesce(p_title, '')) = '' then raise exception 'Give it a name.'; end if;
